import React, {useCallback, useEffect, useMemo, useState, useRef} from 'react';
import DXTaxonomyFilter, {TaxFilterProps, TaxonomyFilterProps} from '../../DXTaxonomyFilter/DXTaxonomyFilter';
import './EventFilters.scss';

const SearchIcon = ({className = ''}) => (
    <svg className={className} width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path
            d="M10 17C13.866 17 17 13.866 17 10C17 6.13401 13.866 3 10 3C6.13401 3 3 6.13401 3 10C3 13.866 6.13401 17 10 17Z"
            stroke="#14181F" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M15 15L21 21" stroke="#14181F" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
);

interface EventFiltersProps {
    searchLabel?: string;
    searchPlaceholder?: string;
    searchTerm: string;
    selectedMonths: string[];
    selectedTags: string[];
    selectedFrequency?: string;
    availableMonths: string[];
    availableTags?: string[];
    availableFrequencies?: string[];
    onFilterChange: (filters: { searchTerm: string; selectedMonths: string[]; selectedTags: string[]; selectedFrequency?: string; }) => void;
    onClearFilters: () => void;
    activeFilterCount: number;
    items?: Array<Record<string, unknown>>;
    filteredCount?: number;
    showSearch?: boolean;
    showMonthYear?: boolean;
    showTags?: boolean;
    showRecurrence?: boolean;
    locale?: string;
}

const EventFilters: React.FC<EventFiltersProps> = ({
    searchLabel = 'Search events',
    searchPlaceholder = 'Type to search events...',
    searchTerm,
    selectedMonths,
    selectedTags,
    selectedFrequency,
    availableMonths,
    availableTags = [],
    availableFrequencies = [],
    onFilterChange,
    onClearFilters,
    activeFilterCount,
    items = [],
    filteredCount,
    showSearch = true,
    showMonthYear = true,
    showTags = true,
    showRecurrence = true,
    locale = 'en-US'
} ) => {
    const [filters, setFilters] = useState<TaxFilterProps[]>( [] );

    const resolvedLocale = useMemo( () => {
        try {
            return new Intl.DateTimeFormat( locale ).resolvedOptions().locale || 'en-US';
        } catch {
            return 'en-US';
        }
    }, [locale] );

    const monthYearFormatter = useMemo( () => {
        return new Intl.DateTimeFormat( resolvedLocale, {
            month: 'long',
            year: 'numeric',
            timeZone: 'UTC'
        } );
    }, [resolvedLocale] );

    const normalizeMonthLabel = useCallback( ( label: string ): string => {
        return label
            .normalize( 'NFD' )
            .replace( /[\u0300-\u036f]/g, '' )
            .replace( /[.,،。]+$/g, '' )
            .toLowerCase()
            .replace( /\s+/g, ' ' )
            .trim();
    }, [] );

    // Use a ref for the mapping so it is stable across renders
    const monthLabelToValueRef = useRef<Record<string, string>>({});
    const monthLabels = useMemo(() => {
        const map: Record<string, string> = {};
        let labels: string[] = [];
        if (showMonthYear && availableMonths.length > 0) {
            labels = availableMonths.reduce<string[]>( ( acc, month ) => {
                const match = /^([0-9]{4})-([0-9]{2})$/.exec( month );
                if ( !match ) return acc;

                const year = Number( match[1] );
                const monthNum = Number( match[2] );
                if ( !Number.isInteger( year ) || !Number.isInteger( monthNum ) ) return acc;
                if ( monthNum < 1 || monthNum > 12 ) return acc;

                const dt = new Date( Date.UTC( year, monthNum - 1, 1 ) );
                if ( Number.isNaN( dt.getTime() ) ) return acc;

                const label = monthYearFormatter.format( dt );
                const normalizedLabel = normalizeMonthLabel( label );
                map[normalizedLabel] = month;
                acc.push( label );
                return acc;
            }, [] );
        }
        monthLabelToValueRef.current = map;
        return labels;
    }, [showMonthYear, availableMonths, monthYearFormatter, normalizeMonthLabel]);

    // Helper: ensure selectedMonth is always a valid YYYY-MM from availableMonths
    const getValidMonthValue = (label: string): string => {
        // Normalize label to match map keys across locale differences
        const normalizedLabel = normalizeMonthLabel( label );
        const value = monthLabelToValueRef.current[normalizedLabel];
        // Only return if it's in availableMonths
        if (value && availableMonths.includes(value)) {
            return value;
        }
      // Fallback: try to parse the label directly as a date
      try {
        const parsed = new Date( label );
        if ( !isNaN( parsed.getTime() ) ) {
          const year = parsed.getFullYear();
          const month = String( parsed.getMonth() + 1 ).padStart( 2, '0' );
          const fallbackValue = `${year}-${month}`;
          if ( availableMonths.includes( fallbackValue ) ) {
            return fallbackValue;
          }
        }
      } catch {
        // Ignore parsing errors
      }
        return '';
    };

    // Use ref to track previous dependencies and prevent infinite loops
    const prevDepsRef = useRef<{
        showMonthYear: boolean;
        showSearch: boolean;
        showTags: boolean;
        showRecurrence: boolean;
        availableMonths: string[];
        availableTags: string[];
        searchLabel: string;
    }>();

    // Initialize filters based on available data and props
    useEffect(() => {
        const currentDeps = {
            showMonthYear,
            showSearch,
            showTags,
            showRecurrence,
            availableMonths,
            availableTags,
            searchLabel
        };

        // Check if dependencies actually changed
        const prevDeps = prevDepsRef.current;
        if (prevDeps &&
            prevDeps.showMonthYear === showMonthYear &&
            prevDeps.showSearch === showSearch &&
            prevDeps.showTags === showTags &&
            prevDeps.showRecurrence === showRecurrence &&
            JSON.stringify(prevDeps.availableMonths) === JSON.stringify(availableMonths) &&
            JSON.stringify(prevDeps.availableTags) === JSON.stringify(availableTags) &&
            prevDeps.searchLabel === searchLabel
        ) {
            return; // No changes, skip update
        }

        const newFilters: TaxFilterProps[] = [];

        // Note: Search filter is handled by DXTaxonomyFilter's built-in search functionality
        // We don't need to add it to the custom filters array

        // Add month filter if enabled
        if (showMonthYear && monthLabels.length > 0) {
            newFilters.push({
                label: 'Month',
                type: 'select',
                attribute: 'month',
                values: monthLabels
            });
        }

        // Add tags filter if enabled
        if (showTags && availableTags?.length > 0) {
            newFilters.push({
                label: 'Tags',
                type: 'select',
                attribute: 'tags',
                values: availableTags
            });
        }

        // Add recurrence filters if enabled
        if (showRecurrence) {
            newFilters.push({
                label: 'Recurrence',
                type: 'select',
                attribute: 'frequency',
                values: ['Single Day Event', 'Daily', 'Weekly', 'Monthly', 'Yearly']
            });
        }

        prevDepsRef.current = currentDeps;
        setFilters(newFilters);
    }, [showMonthYear, showSearch, showTags, showRecurrence, availableMonths, availableTags, searchLabel, monthLabels]);



    function handleFilterChangeFromTaxonomy(selectedFilters: string[]) {
        let newSearchTerm = searchTerm; // Preserve existing search term
        const newSelectedTags: string[] = [];
        let newSelectedMonths: string[] = Array.isArray(selectedMonths) ? [...selectedMonths] : [];
        let newSelectedFrequency = selectedFrequency;

        // Reset all filters first, then re-apply based on selectedFilters
        newSelectedMonths = [];
        newSelectedFrequency = '';
        newSearchTerm = '';

        selectedFilters.forEach(filter => {
            const [type, ...valueParts] = filter.split(':');
            const value = valueParts.join(':');

            if (type === '_search') {
                newSearchTerm = value;
            } else if (type === 'tag' || type === 'tags') {
                newSelectedTags.push(value);
            } else if (type === 'month') {
                // value is the label, map to valid YYYY-MM using helper
                const monthValue = getValidMonthValue(value);
                if (monthValue && !newSelectedMonths.includes(monthValue)) {
                    newSelectedMonths.push(monthValue);
                }
            } else if (type === 'frequency') {
                newSelectedFrequency = value;
            }
        });

        // Remove empty and duplicate values
        const uniqueMonths = Array.from(new Set(newSelectedMonths.filter(Boolean)));
        onFilterChange({
            searchTerm: newSearchTerm,
            selectedMonths: uniqueMonths,
            selectedTags: newSelectedTags,
            selectedFrequency: newSelectedFrequency
        });
    }

    const taxonomyProps: TaxonomyFilterProps = {
        totalItems: items.length,
        filters: filters,
        hideSearch: !showSearch,
        filteredCount: filteredCount ?? items.length,
        filterItems: handleFilterChangeFromTaxonomy,
        searchLabel: searchLabel || 'Search events',
        searchPlaceholder: searchPlaceholder || 'Type to search...',
        icons: {
            filter: 'ci-Filter',
            filterClose: 'ci-Close_MD',
            search: <SearchIcon className="text-muted" />
        }
    };


    // Return null only if all filters are disabled
    if (!showSearch && filters.length === 0 && !showMonthYear && !showTags && !showRecurrence) return null;

    return (
        <div className="cec-upcoming-events__filters">
            <div className="cec-upcoming-events__filters-row">
                {}
                {(showSearch || filters.length > 0) && (
                    <DXTaxonomyFilter
                        {...taxonomyProps}
                        onClearFilters={onClearFilters}
                        clearFiltersLabel="Clear Filters"
                        hideClearFilters={activeFilterCount === 0}
                    />
                )}
            </div>
        </div>
    );
};

export default EventFilters;
